-- One donor cornea: the case every image and analysis run belongs to. The id is a random UUID
-- generated by the server, never a real tissue or donor number.
--
-- Sensitive fields (*_enc) are encrypted by the backend (AES-256-GCM, FieldCipher) before they
-- reach the database; their associated data binds "donor_cases.<column>" and the row id.
-- The tissue number is found by its keyed HMAC (tissue_number_bidx, BlindIndex), never by value.
-- Measurements and slit-lamp findings are not identifying and stay plain, so they can be queried.

CREATE TABLE donor_cases (
    id                           UUID                     PRIMARY KEY,
    tissue_number_enc            BYTEA                    NOT NULL,
    tissue_number_bidx           VARCHAR(64)              NOT NULL,
    donor_identity_enc           BYTEA,
    cause_of_death_enc           BYTEA,
    medical_history_enc          BYTEA,
    serology_enc                 BYTEA,
    clinical_notes_enc           BYTEA,
    -- Derived from the serology results (false = any positive, null = not all known), for the
    -- recommendation hard filter. Health data: only exposed to authorised roles by the backend.
    serology_clear               BOOLEAN,
    donor_age_years              INTEGER,
    death_to_preservation_hours  DOUBLE PRECISION,
    preservation_date            DATE,
    ecd                          DOUBLE PRECISION,
    cv                           DOUBLE PRECISION,
    hex_percent                  DOUBLE PRECISION,
    sd                           DOUBLE PRECISION,
    total_cell_count             INTEGER,
    total_area_um2               DOUBLE PRECISION,
    slit_lamp_json               TEXT,
    created_by                   BIGINT                   NOT NULL,
    created_at                   TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_at                   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uk_donor_cases_tissue_number UNIQUE (tissue_number_bidx),
    CONSTRAINT fk_donor_cases_user FOREIGN KEY (created_by) REFERENCES app_users (id)
);

CREATE INDEX idx_donor_cases_created_by ON donor_cases (created_by);

-- Link images and runs to their case. From here on case_id holds the same case id as text (never
-- the tissue ID); rows written before this migration keep their old case_id and no donor_case_id.
ALTER TABLE analysis_images ADD COLUMN donor_case_id UUID;
ALTER TABLE analysis_images
    ADD CONSTRAINT fk_analysis_images_donor_case FOREIGN KEY (donor_case_id) REFERENCES donor_cases (id);
CREATE INDEX idx_analysis_images_donor_case_id ON analysis_images (donor_case_id);

ALTER TABLE analysis_runs ADD COLUMN donor_case_id UUID;
ALTER TABLE analysis_runs
    ADD CONSTRAINT fk_analysis_runs_donor_case FOREIGN KEY (donor_case_id) REFERENCES donor_cases (id);
CREATE INDEX idx_analysis_runs_donor_case_id ON analysis_runs (donor_case_id);

ALTER TABLE disease_analysis_runs ADD COLUMN donor_case_id UUID;
ALTER TABLE disease_analysis_runs
    ADD CONSTRAINT fk_disease_runs_donor_case FOREIGN KEY (donor_case_id) REFERENCES donor_cases (id);
CREATE INDEX idx_disease_runs_donor_case_id ON disease_analysis_runs (donor_case_id);

ALTER TABLE grading_analysis_runs ADD COLUMN donor_case_id UUID;
ALTER TABLE grading_analysis_runs
    ADD CONSTRAINT fk_grading_runs_donor_case FOREIGN KEY (donor_case_id) REFERENCES donor_cases (id);
CREATE INDEX idx_grading_runs_donor_case_id ON grading_analysis_runs (donor_case_id);

ALTER TABLE cellular_analysis_runs ADD COLUMN donor_case_id UUID;
ALTER TABLE cellular_analysis_runs
    ADD CONSTRAINT fk_cellular_runs_donor_case FOREIGN KEY (donor_case_id) REFERENCES donor_cases (id);
CREATE INDEX idx_cellular_runs_donor_case_id ON cellular_analysis_runs (donor_case_id);
